ReaServer::ReaServer(const std::string& log_level, ModelManager* model_manager,
             BackendManager* backend_manager)
    : WrappedServer("rea", log_level, model_manager, backend_manager) {}

void ReaServer::load(const std::string& model_name, const ModelInfo& model_info,
                 const RecipeOptions& options, bool /*do_not_upgrade*/) {
    const std::string checkpoint = model_info.checkpoint();
    if (checkpoint.empty()) {
        throw std::runtime_error("rea model checkpoint is empty for: " + model_name);
    }
    const std::string executable = BackendUtils::get_backend_binary_path(*rea::spec(), "system");

    std::string device = options.get_option("rea_device");
    if (device.empty()) {
        device = "0";
    }
    std::string tmpl = options.get_option("rea_args");
    if (tmpl.empty()) {
        tmpl = kArgsTemplate;
    }

    port_ = choose_port();
    if (port_ == 0) {
        throw std::runtime_error("Failed to allocate a port for rea");
    }

    ServerCommand command;
    command.program = executable;
    command.args = split_args(fill(tmpl, checkpoint, port_, device));
    command.env = {
    };
    for (auto& kv : command.env) {
        kv.second = fill(kv.second, checkpoint, port_, device);
    }
    command.port = port_;
    command.ready_endpoint = kReadyPath;

    LOG(INFO, "Rea") << "Starting " << executable << " for " << checkpoint << " on port " << port_
                       << " (device " << device << ")" << std::endl;
    const bool inherit_output = (log_level_ == "info") || (log_level_ == "debug");
    start_server(std::make_unique<NativeProcess>(ProcessOutput{inherit_output, true}), command,
                 kReadyTimeoutSeconds);

    // The health route can answer before the engine is ready (e.g. while weights load).
    if (std::string(kReadyField).size() > 0) {
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(kReadyTimeoutSeconds);
        std::string last;
        while (true) {
            try {
                const json health = forward_get_request(kReadyPath, 5);
                last = health.value(kReadyField, std::string{});
            } catch (...) {
                last = "";
            }
            if (contains(kReadyValues, last)) break;
            if (contains(kErrorValues, last) || std::chrono::steady_clock::now() > deadline) {
                stop_server();
                throw std::runtime_error(std::string("rea engine did not become ready (") + kReadyField +
                                         "=\"" + last + "\")");
            }
            std::this_thread::sleep_for(std::chrono::seconds(2));
        }
    }

    // Refuse a mislabelled engine: /v1/models must report the expected owned_by.
    bool identified = false;
    try {
        const json models = forward_get_request("/v1/models", 10);
        for (const auto& m : models.value("data", json::array())) {
            if (m.value("owned_by", std::string{}) == kOwnedBy) identified = true;
        }
    } catch (...) {
    }
    if (!identified) {
        stop_server();
        throw std::runtime_error(std::string("rea: /v1/models does not report owned_by=") + kOwnedBy +
                                 "; refusing a mislabelled engine");
    }
    LOG(INFO, "Rea") << kOwnedBy << " ready on port " << port_ << std::endl;
}

json ReaServer::chat_completion(const json& request) {
    return forward_request("/v1/chat/completions", request);
}

json ReaServer::completion(const json& request) {
    return forward_request("/v1/completions", request);
}

std::map<std::string, nlohmann::json> ReaServer::get_additional_telemetry() {
    if (get_backend_port() <= 0 || std::string(kTelemetryPath).empty()) {
        return {};
    }
    std::map<std::string, nlohmann::json> out;
    try {
        out["rea_stats"] = forward_get_request(kTelemetryPath, 2);
    } catch (...) {
        out["rea_stats"] = nullptr;
    }
    return out;
}

std::string ReaServer::get_additional_telemetry_url() const {
    if (get_backend_port() <= 0 || std::string(kTelemetryPath).empty()) {
        return "";
    }
    return get_base_url() + kTelemetryPath;
}

